package assignment.game;

import assignment.actions.Action;
import assignment.actions.ActionResult;
import assignment.actions.Exit;
import assignment.actions.InvalidInput;
import assignment.actions.Move;
import assignment.actions.Undo;
import assignment.entities.Box;
import assignment.entities.Empty;
import assignment.entities.Entity;
import assignment.entities.Player;
import assignment.entities.Wall;
import assignment.game.GameState;
import assignment.game.Position;
import assignment.game.SokobanGame;
import assignment.utils.ShouldNotReachException;
import assignment.utils.StringResources;
import assignment.utils.NotImplementedException;
import assignment.utils.ShouldNotReachException;

import static assignment.utils.StringResources.PLAYER_NOT_FOUND;
import static assignment.utils.StringResources.UNDO_QUOTA_RUN_OUT;


/**
 * A base implementation of Sokoban Game.
 */
public abstract class AbstractSokobanGame implements SokobanGame {
    protected final GameState state;

    private boolean isExitSpecified = false;

    protected AbstractSokobanGame(GameState gameState) {
        this.state = gameState;
    }

    /**
     * @return True is the game should stop running.
     * For example when the user specified to exit the game or the user won the game.
     */
    protected boolean shouldStop() {
        return isExitSpecified || state.isWin();
    }

    /**
     * @param action The action received from the user.
     * @return The result of the action.
     */
    protected ActionResult processAction(Action action) {
        if (action instanceof Exit) {
            isExitSpecified = true;
            return new ActionResult.Success(action);
        } else if (action instanceof Undo) {
            if (state.getUndoQuota().isPresent() && state.getUndoQuota().get() <= 0) {
                return new ActionResult.Failed(action, UNDO_QUOTA_RUN_OUT);
            }
            state.undo();
            return new ActionResult.Success(action);
        } else if (action instanceof Move) {
            Move move = (Move) action;
            int playerId = action.getInitiator();
            Position currentPos = state.getPlayerPositionById(playerId);

            if (currentPos == null) {
                return new ActionResult.Failed(action, PLAYER_NOT_FOUND);
            }

            Position nextPos = move.nextPosition(currentPos);

            // Check if next position is valid
            Entity nextEntity = state.getEntity(nextPos);
            if (nextEntity instanceof Wall) {
                return new ActionResult.Failed(action, "Cannot move into a wall");
            }

            if (nextEntity instanceof Box) {
                Box box = (Box) nextEntity;
                Position boxNextPos = move.nextPosition(nextPos);
                Entity boxNextEntity = state.getEntity(boxNextPos);

                if (!(boxNextEntity instanceof Empty)) {
                    return new ActionResult.Failed(action, "Cannot push box - blocked");
                }

                // Move both player and box
                state.move(nextPos, boxNextPos);
                state.move(currentPos, nextPos);
            } else {
                // Just move player
                state.move(currentPos, nextPos);
            }

            return new ActionResult.Success(action);
        } else if (action instanceof InvalidInput) {
            return new ActionResult.Failed(action, ((InvalidInput) action).getMessage());
        }

        throw new ShouldNotReachException();
    }
}
```

